package com.wiseway.service;
import com.wiseway.api.ApiDtos.*; import com.wiseway.domain.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class RecommendationService {
 public CompareResponse compare(CompareRequest r, Set<String> excluded){var p=r.preference()==null?PreferenceProfile.BALANCED:r.preference();var c=r.constraints();var result=RecommendationEngine.recommend(SampleOptions.all(),p,new RecommendationEngine.Constraints(c==null?null:c.maxFare(),r.departureAt(),c==null?null:c.arriveBy()),excluded);return response(result);}
 public PlanBResponse planB(PlanBRequest r){var excluded=new HashSet<>(Optional.ofNullable(r.excludeOptionIds()).orElse(List.of())); if((r.scenario()==PlanBScenario.MISSED_SERVICE||r.scenario()==PlanBScenario.ROUTE_DISRUPTED)&&excluded.isEmpty()) excluded.add(r.scenario()==PlanBScenario.MISSED_SERVICE?"bus-1":"train-1"); var c=r.constraints();var p=r.preference()==null?PreferenceProfile.BALANCED:r.preference();var result=RecommendationEngine.recommend(SampleOptions.all(),p,new RecommendationEngine.Constraints(c==null?null:c.maxFare(),r.departureAt(),c==null?null:c.arriveBy()),excluded);var options=toOptions(result);return new PlanBResponse(r.scenario(),"SAMPLE_ESTIMATES","Simulated Plan B using sample options; not a live service alert.",options.isEmpty()?null:options.get(0),options.size()>1?options.subList(1,options.size()):List.of(),result.noFit(),result.message());}
 private CompareResponse response(RecommendationEngine.Result r){return new CompareResponse("SAMPLE_ESTIMATES","Demo estimates only; this is not live transit information.",r.feasible().stream().map(this::toOption).toList(),r.infeasible().stream().map(x->new OptionResponse(x.option().id(),x.option().mode(),x.option().durationMinutes(),x.option().estimatedFare(),x.option().currency(),x.option().transfers(),x.option().walkingMinutes(),x.option().description(),null,List.of(),x.reasons())).toList(),r.noFit(),r.message());}
 private List<OptionResponse> toOptions(RecommendationEngine.Result r){return r.feasible().stream().map(this::toOption).toList();} private OptionResponse toOption(RecommendationEngine.RankedOption x){return new OptionResponse(x.option().id(),x.option().mode(),x.option().durationMinutes(),x.option().estimatedFare(),x.option().currency(),x.option().transfers(),x.option().walkingMinutes(),x.option().description(),x.score(),x.reasons(),List.of());}
}
